    pub fn roles(&self) -> &[u32] { &self.roles }
    pub fn initial(&self) -> State {
        let mut s = State::default();
        s.f_castling_right = self.st.r_init_castling_right.order.clone();
        s.f_cell = self.st.r_init_cell.order.clone();
        s.f_control = self.st.r_init_control.order.clone();
        s.f_halfmove = self.st.r_init_halfmove.order.clone();
        s.sort();
        s
    }
    /// The state's rows and the turn's into a fresh evaluation.
    fn load(&self, s: &State, does: &[(u32, u32)]) -> Dy {
        let mut d = Dy::new();
        for r in &s.f_castling_right { d.r_true_castling_right.add(*r); }
        for r in &s.f_cell { d.r_true_cell.add(*r); }
        for r in &s.f_control { d.r_true_control.add(*r); }
        for r in &s.f_ep_square { d.r_true_ep_square.add(*r); }
        for r in &s.f_halfmove { d.r_true_halfmove.add(*r); }
        for (r, m) in does { d.r_does.add([*r, *m]); }
        d
    }
    fn run(&mut self, d: &mut Dy, which: &[usize]) {
        for &k in which {
            if self.profiling {
                let t = std::time::Instant::now();
                let (a, b, c) = run_piece(&self.st, d, &mut self.tm, k);
                let p = &mut self.prof[k];
                p.calls += 1; p.nanos += t.elapsed().as_nanos() as u64; p.rows += a; p.visits += b; p.probes += c;
            } else {
                run_piece(&self.st, d, &mut self.tm, k);
            }
        }
    }
    fn read(&mut self, s: &State) -> Reading {
        if let Some((k, r)) = &self.last { if k == s { return r.clone(); } }
        let mut d = self.load(s, &[]);
        self.run(&mut d, READ_CONE);
        let rd = Reading { legal: d.r_legal.order.iter().map(|x| (x[0], x[1])).collect(), terminal: !d.r_terminal.order.is_empty(), goals: d.r_goal.order.iter().map(|x| (x[0], x[1])).collect() };
        self.last = Some((s.clone(), rd.clone()));
        rd
    }
    pub fn mover(&mut self, s: &State) -> Option<usize> {
        let rd = self.read(s);
        if rd.terminal { return None; }
        self.roles.iter().position(|r| rd.legal.iter().any(|(q, m)| q == r && *m != self.noop))
    }
    pub fn moves(&mut self, s: &State) -> Vec<u32> {
        let Some(r) = self.mover(s) else { return vec![] };
        let rd = self.read(s);
        rd.legal.iter().filter(|(q, _)| *q == self.roles[r]).map(|(_, m)| *m).collect()
    }
    pub fn terminal(&mut self, s: &State) -> bool { self.read(s).terminal }
    pub fn outcome(&mut self, s: &State) -> Option<Vec<i64>> {
        let rd = self.read(s);
        if !rd.terminal { return None; }
        Some(self.roles.iter().map(|r| rd.goals.iter().find(|(q, _)| q == r).and_then(|(_, v)| self.tm.name(*v).parse().ok()).unwrap_or(0)).collect())
    }
    pub fn next(&mut self, s: &State, mv: u32) -> State {
        let me = self.mover(s);
        let does: Vec<(u32, u32)> = self.roles.iter().enumerate().map(|(i, r)| (*r, if Some(i) == me { mv } else { self.noop })).collect();
        let mut d = self.load(s, &does);
        self.run(&mut d, NEXT_CONE);
        let mut n = State::default();
        n.f_castling_right = d.r_next_castling_right.order.clone();
        n.f_cell = d.r_next_cell.order.clone();
        n.f_control = d.r_next_control.order.clone();
        n.f_ep_square = d.r_next_ep_square.order.clone();
        n.f_halfmove = d.r_next_halfmove.order.clone();
        n.sort();
        n
    }
    pub fn sym(&self, name: &str) -> Option<u32> { SYMS.binary_search(&name).ok().map(|i| i as u32) }
    pub fn render(&self, t: u32) -> String { self.tm.render(t) }
    /// A term from its text: a constant, or (functor arg ...).
    pub fn term(&mut self, text: &str) -> Result<u32, String> {
        let spaced = text.replace('(', " ( ").replace(')', " ) ");
        let toks: Vec<&str> = spaced.split_whitespace().collect();
        let mut i = 0;
        let t = self.term_at(&toks, &mut i)?;
        if i != toks.len() { return Err(format!("trailing text in a term: {text}")); }
        Ok(t)
    }
    fn term_at(&mut self, toks: &[&str], i: &mut usize) -> Result<u32, String> {
        let tok = *toks.get(*i).ok_or("a term ends too soon")?;
        *i += 1;
        if tok != "(" { return self.sym(tok).ok_or_else(|| format!("no symbol {tok} in the description")); }
        let f = *toks.get(*i).ok_or("a term ends too soon")?;
        *i += 1;
        let ft = self.sym(f).ok_or_else(|| format!("no symbol {f} in the description"))?;
        let mut args = vec![];
        while toks.get(*i) != Some(&")") { if *i >= toks.len() { return Err("a term is not closed".into()); } args.push(self.term_at(toks, i)?); }
        *i += 1;
        Ok(self.tm.fun(ft, &args))
    }
    /// The state from its facts: (fluent, arguments as text).
    pub fn state_of_facts(&mut self, facts: &[(String, Vec<String>)]) -> Result<State, String> {
        let mut s = State::default();
        for (rel, args) in facts {
            let mut ts = Vec::with_capacity(args.len());
            for a in args { ts.push(self.term(a)?); }
            match rel.as_str() {
                "castling_right" => { if ts.len() != 2 { return Err(format!("castling_right takes 2 arguments")); } let mut r = [0u32; 2]; r.copy_from_slice(&ts); s.f_castling_right.push(r); }
                "cell" => { if ts.len() != 4 { return Err(format!("cell takes 4 arguments")); } let mut r = [0u32; 4]; r.copy_from_slice(&ts); s.f_cell.push(r); }
                "control" => { if ts.len() != 1 { return Err(format!("control takes 1 arguments")); } let mut r = [0u32; 1]; r.copy_from_slice(&ts); s.f_control.push(r); }
                "ep_square" => { if ts.len() != 2 { return Err(format!("ep_square takes 2 arguments")); } let mut r = [0u32; 2]; r.copy_from_slice(&ts); s.f_ep_square.push(r); }
                "halfmove" => { if ts.len() != 1 { return Err(format!("halfmove takes 1 arguments")); } let mut r = [0u32; 1]; r.copy_from_slice(&ts); s.f_halfmove.push(r); }
                other => return Err(format!("the description has no fluent {other}")),
            }
        }
        s.sort();
        Ok(s)
    }
    /// The facts of a state: (fluent, arguments as text), sorted.
    pub fn facts_of(&self, s: &State) -> Vec<(String, Vec<String>)> {
        let mut out = vec![];
        for r in &s.f_castling_right { out.push(("castling_right".to_string(), r.iter().map(|t| self.tm.render(*t)).collect())); }
        for r in &s.f_cell { out.push(("cell".to_string(), r.iter().map(|t| self.tm.render(*t)).collect())); }
        for r in &s.f_control { out.push(("control".to_string(), r.iter().map(|t| self.tm.render(*t)).collect())); }
        for r in &s.f_ep_square { out.push(("ep_square".to_string(), r.iter().map(|t| self.tm.render(*t)).collect())); }
        for r in &s.f_halfmove { out.push(("halfmove".to_string(), r.iter().map(|t| self.tm.render(*t)).collect())); }
        out.sort();
        out
    }
